questionCorrectionRespond($db,$admin,$id,1,$hash,'rejected','<script>already correct</script>');
erpEqual($db->query('SELECT * FROM questions WHERE id='.$qid)->fetch(PDO::FETCH_ASSOC),$before,'Reject leaves source unchanged');
erpEqual(questionCorrectionCounts($db,$teacher)['unread'],1,'Response starts unread');
erpReject(fn()=>questionCorrectionDetail($db,$a['school_admin'],$id),'Admin cannot read teacher report');
